class LRUCache {
  constructor () {
    this.max = 1000
    this.map = new Map()
  }

  get (key) {
    const value = this.map.get(key)
    if (value === undefined) {
      return undefined
    }

    // mark as most recently used
    this.map.delete(key)
    this.map.set(key, value)
    return value
  }

  delete (key) {
    return this.map.delete(key)
  }

  set (key, value) {
    if (value === undefined) {
      return this
    }

    if (this.map.has(key)) {
      this.map.delete(key)
    } else if (this.map.size >= this.max) {
      // evict least recently used entry (the oldest insertion order)
      const oldestKey = this.map.keys().next().value
      this.map.delete(oldestKey)
    }

    this.map.set(key, value)
    return this
  }
}

