const parse = require('./parse.js')

const diff = (version1, version2) => {
  const v1 = parse(version1, null, true)
  const v2 = parse(version2, null, true)
  const comparison = v1.compare(v2)

  if (comparison === 0) {
    return null
  }

  const v1Higher = comparison > 0
  const highVersion = v1Higher ? v1 : v2
  const lowVersion = v1Higher ? v2 : v1
  const highHasPre = !!highVersion.prerelease.length
  const lowHasPre = !!lowVersion.prerelease.length

  // stepping OUT of a prerelease: the higher version is a release while the
  // lower version is a prerelease.
  if (!highHasPre && lowHasPre) {
    if (highVersion.major !== lowVersion.major) {
      return 'major'
    }
    if (highVersion.minor !== lowVersion.minor) {
      return 'minor'
    }
    if (highVersion.patch !== lowVersion.patch) {
      return 'patch'
    }
    // the main version is unchanged: classify by how much is left behind
    if (lowVersion.minor === 0 && lowVersion.patch === 0) {
      return 'major'
    }
    if (lowVersion.minor !== 0 && lowVersion.patch === 0) {
      return 'minor'
    }
    return 'patch'
  }

  // add the `pre` prefix when moving to/within a prerelease version
  const prefix = highHasPre ? 'pre' : ''

  // two prereleases of the same main version, or with a differing main version
  if (highHasPre && lowHasPre) {
    if (highVersion.major !== lowVersion.major) {
      return 'major'
    }
    if (highVersion.minor !== lowVersion.minor) {
      return 'minor'
    }
    if (highVersion.patch !== lowVersion.patch) {
      return 'patch'
    }
    return 'prerelease'
  }

  // ordinary release step, or stepping INTO a prerelease
  if (highVersion.major !== lowVersion.major) {
    return prefix + 'major'
  }
  if (highVersion.minor !== lowVersion.minor) {
    return prefix + 'minor'
  }
  if (highVersion.patch !== lowVersion.patch) {
    return prefix + 'patch'
  }

  // high is a prerelease, low is a release, and the main version is unchanged
  return 'prerelease'
}

